using System.Collections.Generic; using NUnit.Framework; using SuijinMaterials.World;
namespace SuijinMaterials.Tests { [TestFixture] public sealed class VegetationInstallerTests { [Test] public void Refresh_does_not_duplicate_and_uninstall_restores_thistle(){var f=new Fake();var i=new VegetationInstaller(f,_=>{});i.Install(Default());i.Install(Default());Assert.Multiple(()=>{Assert.That(f.Custom.Count,Is.EqualTo(2));Assert.That(f.ThistleMask,Is.EqualTo(1));});i.Uninstall();Assert.Multiple(()=>{Assert.That(f.ThistleMask,Is.EqualTo(3));Assert.That(f.Custom,Is.Empty);});}private static WorldSettingsSnapshot Default()=>new WorldSettingsSnapshot(new Dictionary<string,WorldRuleSettings>{{"yarrow-meadows",new WorldRuleSettings(true,.35,1,2,1,240,0,false)},{"nightbloom-swamp",new WorldRuleSettings(true,1,1,1,1,240,0,false)},{"yggdrasil-branch-roots",new WorldRuleSettings(true,.35,1,1,1,0,0,false)}});private sealed class Fake:IVegetationFacade{public int ThistleMask=3;public readonly HashSet<string> Custom=new HashSet<string>();public int GetThistleBiomeMask()=>ThistleMask;public void SetThistleBiomeMask(int x)=>ThistleMask=x;public void AddYarrow(WorldRuleSettings x)=>Custom.Add(VegetationInstaller.YarrowVegetationName);public void AddNightbloom(WorldRuleSettings x)=>Custom.Add(VegetationInstaller.NightbloomVegetationName);public void Remove(string x)=>Custom.Remove(x);} } }
